    @push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('employeeWizard'),steps=[...document.querySelectorAll('.nx-step')],panes=[...document.querySelectorAll('.nx-step-pane')],back=document.getElementById('employeeBack'),next=document.getElementById('employeeNext'),submit=document.getElementById('employeeSubmit');let current=0;const errorNames=@json(array_keys($errors->toArray()));const map={first_name:0,work_email:1,phone:1,department:2,designation:2,role:2,premises:2,identity_documents:3,verification:3,basic_salary:4,bank_details:4,benefits_allowances:5,education_skills:6,safety:6,assets_access:7,exit_separation:7};if(errorNames.length){current=Math.min(...errorNames.map(x=>map[x.split('.')[0]]??0));errorNames.forEach(name=>{const el=form.querySelector(`[name="${name}"]`)||form.querySelector(`[name^="${name.split('.')[0]}["]`);el?.classList.add('is-invalid')});steps[current].classList.add('error')}function show(i){current=Math.max(0,Math.min(i,panes.length-1));panes.forEach((p,x)=>p.classList.toggle('active',x===current));steps.forEach((s,x)=>s.classList.toggle('active',x===current));back.disabled=current===0;next.classList.toggle('d-none',current===panes.length-1);submit.classList.toggle('d-none',current!==panes.length-1);window.scrollTo({top:0,behavior:'smooth'})}steps.forEach((s,i)=>s.onclick=()=>show(i));back.onclick=()=>show(current-1);next.onclick=()=>{if(!NxValidate.validateContainer(panes[current])){steps[current].classList.add('error');return}steps[current].classList.remove('error');show(current+1)};form.addEventListener('nx:reveal',e=>{show(Number(e.detail.step)-1);e.preventDefault()});show(current)});</script>@endpush
</x-app-layout>
